from datetime import date, timedelta

def closure_ranges(days):
    dates = sorted(date.fromisoformat(value) for value in days)
    if not dates:
        return []
    result = []
    start = previous = dates[0]
    for current in dates[1:]:
        if current.day == previous.day + 1:
            previous = current
        else:
            result.append({'start': start.isoformat(), 'end': previous.isoformat()})
            start = previous = current
    result.append({'start': start.isoformat(), 'end': previous.isoformat()})
    return result

